package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;@Component public class PerformanceAppealPermissionGuard{public static final String FEATURE="primehr.performance-appeal";private final AdministrativeAuthorizationClient client;public PerformanceAppealPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public PermissionDataScope require(PrimeHrAction a,String token){EffectiveFeaturePermission p=client.resolve(FEATURE,token);boolean allowed=p.administrator()||p.canAccess()&&switch(a){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();default->false;};if(!allowed)throw new AccessDeniedException("Performance appeal permission is required");PermissionDataScope s=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(s!=PermissionDataScope.OWN_RECORDS&&s!=PermissionDataScope.ASSIGNED_RECORDS&&s!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Performance appeal scope is not permitted");return s;}}
